 {modal==='groupAssign'&&<label>{t('groups')}<select value={form.group_id||''} onChange={e=>setForm({...form,group_id:e.target.value})}><option value="">{t('select')}</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label>}
