 {!['discovery','import'].includes(modal)&&<div className="modal-actions"><button className="button" onClick={()=>setModal('')}>{t('cancel')}</button><button className="button primary" disabled={busy||(modal==='rename'&&plans.some(p=>p.conflict))} onClick={modal==='rename'?applyRename:submitModal}>{t(busy?'longRunning':modal==='rename'?'renameApply':modal==='node'?'nodeStatus':'confirm')}</button></div>}
